-- ===============================================
-- BingePlay Streaming Platform — Database Setup
-- The Unlox Academy · Week 4 Minor Project
-- ===============================================
--
-- Tables: users, subscriptions, shows, watch_sessions, ratings
-- Approx rows: 3000 users, 4497 subs, 100 shows, 100351 sessions, 5000 ratings
--

DROP DATABASE IF EXISTS bingeplay;
CREATE DATABASE bingeplay;
USE bingeplay;

-- =========== USERS ===========
CREATE TABLE users (
    user_id VARCHAR(10) PRIMARY KEY,
    name VARCHAR(100) NOT NULL,
    signup_date DATE NOT NULL,
    city VARCHAR(50) NOT NULL,
    age_group VARCHAR(10) NOT NULL,
    referral_source VARCHAR(30) NOT NULL,
    INDEX idx_signup_date (signup_date),
    INDEX idx_city (city)
);







-- =========== SHOWS ===========
CREATE TABLE shows (
    show_id VARCHAR(10) PRIMARY KEY,
    title VARCHAR(150) NOT NULL,
    category VARCHAR(30) NOT NULL,
    language VARCHAR(30) NOT NULL,
    release_year INT NOT NULL,
    imdb_rating DECIMAL(3,1) NOT NULL,
    is_original TINYINT NOT NULL,
    min_plan VARCHAR(20) NOT NULL,
    INDEX idx_category (category),
    INDEX idx_language (language)
);


-- =========== SUBSCRIPTIONS ===========
CREATE TABLE subscriptions (
    subscription_id VARCHAR(15) PRIMARY KEY,
    user_id VARCHAR(10) NOT NULL,
    plan VARCHAR(20) NOT NULL,
    start_date DATE NOT NULL,
    end_date DATE,
    status VARCHAR(20) NOT NULL,
    monthly_price_inr INT NOT NULL,
    INDEX idx_user (user_id),
    INDEX idx_status (status),
    INDEX idx_start_date (start_date),
    FOREIGN KEY (user_id) REFERENCES users(user_id)
);










-- =========== WATCH_SESSIONS ===========
CREATE TABLE watch_sessions (
    session_id INT PRIMARY KEY,
    user_id VARCHAR(10),
    show_id VARCHAR(10) NOT NULL,
    session_date DATE NOT NULL,
    watch_minutes INT NOT NULL,
    device_type VARCHAR(20) NOT NULL,
    completed TINYINT NOT NULL,
    INDEX idx_user (user_id),
    INDEX idx_show (show_id),
    INDEX idx_session_date (session_date),
    INDEX idx_completed (completed),
    FOREIGN KEY (show_id) REFERENCES shows(show_id)
);






































































































-- =========== RATINGS ===========
CREATE TABLE ratings (
    rating_id INT PRIMARY KEY,
    user_id VARCHAR(10) NOT NULL,
    show_id VARCHAR(10) NOT NULL,
    stars TINYINT NOT NULL,
    rated_date DATE NOT NULL,
    INDEX idx_user (user_id),
    INDEX idx_show (show_id),
    INDEX idx_stars (stars),
    FOREIGN KEY (user_id) REFERENCES users(user_id),
    FOREIGN KEY (show_id) REFERENCES shows(show_id)
);











-- =========== VERIFICATION QUERIES ===========
-- Run these to verify the data loaded correctly:

SELECT 'users' AS tbl, COUNT(*) AS row_count FROM users
UNION ALL SELECT 'subscriptions', COUNT(*) FROM subscriptions
UNION ALL SELECT 'shows', COUNT(*) FROM shows
UNION ALL SELECT 'watch_sessions', COUNT(*) FROM watch_sessions
UNION ALL SELECT 'ratings', COUNT(*) FROM ratings;

-- Expected:
--   users:          3000
--   subscriptions:  4497
--   shows:           100
--   watch_sessions: 100351
--   ratings:        5000

-- Sanity check for NULL trap in watch_sessions:
SELECT COUNT(*) AS null_user_sessions FROM watch_sessions WHERE user_id IS NULL;
-- Expected: 2 (yes — this is intentional. See Q7 in the brief.)

